{
  "title": "Shared Weekend Trip Planner",
  "body": "<div class='todo-app'>
  <header>
    <h1>🏕️ Weekend Trip Planner</h1>
    <p id='count'>3 tasks remaining</p>
  </header>
  <form id='add-form' class='add-form'>
    <input type='text' id='new-task' placeholder='Add a new task...' />
    <button id='add-btn'>Add</button>
  </form>
  <ul id='todo-list'></ul>
</div>",
  "css": "* { box-sizing: border-box; margin: 0; padding: 0; }

.todo-app {
  font-family: 'Segoe UI', system-ui, sans-serif;
  max-width: 420px;
  margin: 32px auto;
  background: #ffffff;
  border-radius: 16px;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.12);
  overflow: hidden;
}

header {
  background: linear-gradient(135deg, #6a89cc, #4a69bd);
  color: white;
  padding: 28px 24px 22px;
  text-align: center;
}

h1 {
  font-size: 1.4rem;
  margin-bottom: 6px;
  letter-spacing: 0.5px;
}

#count {
  font-size: 0.85rem;
  opacity: 0.85;
  font-weight: 500;
}

.add-form {
  display: flex;
  padding: 16px 16px 4px;
  gap: 8px;
  background: #f7f9fc;
  border-bottom: 1px solid #e8ecf2;
}

#new-task {
  flex: 1;
  padding: 10px 14px;
  border: 2px solid #dce3eb;
  border-radius: 10px;
  font-size: 0.95rem;
  outline: none;
  transition: border-color 0.2s;
}

#new-task:focus {
  border-color: #6a89cc;
}

#add-btn {
  padding: 10px 18px;
  background: linear-gradient(135deg, #6a89cc, #4a69bd);
  color: white;
  border: none;
  border-radius: 10px;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.1s, box-shadow 0.2s;
}

#add-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(74, 105, 189, 0.35);
}

#todo-list {
  list-style: none;
  padding: 0;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 20px;
  border-bottom: 1px solid #f0f3f8;
  transition: background 0.15s;
}

.todo-item:hover {
  background: #f9fbfe;
}

.todo-item:last-child {
  border-bottom: none;
}

.todo-checkbox {
  width: 20px;
  height: 20px;
  accent-color: #4a69bd;
  cursor: pointer;
  flex-shrink: 0;
}

.todo-text {
  flex: 1;
  font-size: 0.95rem;
  color: #333;
  transition: all 0.2s;
}

.todo-item.done .todo-text {
  text-decoration: line-through;
  color: #a0aab8;
}

.delete-btn {
  padding: 4px 10px;
  background: none;
  border: 1px solid #e0e4ea;
  border-radius: 6px;
  color: #c0392b;
  font-size: 0.78rem;
  cursor: pointer;
  opacity: 0.5;
  transition: opacity 0.15s, background 0.15s;
}

.todo-item:hover .delete-btn {
  opacity: 1;
}

.delete-btn:hover {
  background: #fdf2f2;
  border-color: #e74c3c;
}

.empty-state {
  text-align: center;
  padding: 32px 20px;
  color: #b0b8c5;
  font-size: 0.9rem;
}",
  "scripts": [
    "function renderTodos() { const list = root.byId['todo-list']; let items = state.todos || []; if (!list) return; list.children = []; if (items.length === 0) { list.children.push({ tag: 'li', attrs: {}, text: 'No tasks yet. Add one above!', children: [] }); return; } for (let i = 0; i < items.length; i++) { const todo = items[i]; const itemNode = { tag: 'li', attrs: { class: 'todo-item' + (todo.done ? ' done' : ''), id: 'item-' + todo.id }, children: [ { tag: 'input', attrs: { type: 'checkbox', class: 'todo-checkbox', checked: todo.done, on: { change: () => toggleTodo(todo.id) } } }, { tag: 'span', attrs: { class: 'todo-text' }, text: todo.text }, { tag: 'button', attrs: { class: 'delete-btn', id: 'del-' + todo.id, on: { click: () => deleteTodo(todo.id) } }, text: 'Delete' } ] }; list.children.push(itemNode); } const count = root.byId['count']; if (count) { const remaining = items.filter(t => !t.done).length; const total = items.length; count.text = `${remaining} task${remaining !== 1 ? 's' : ''} remaining${total > 0 && remaining === 0 ? ' — all done! 🎉' : '.'}; ${total > 0 ? (remaining + '/' + total) : ''}`; } updateCount(); } function addItem() { const input = root.byId['new-task']; if (!input || !input.text || input.text.trim() === '') return; let todos = state.todos || []; const id = 'task-' + Date.now(); todos.push({ id: id, text: input.text.trim(), done: false }); state.todos = todos; if (input) { input.text = ''; } renderTodos(); } function toggleTodo(id) { let todos = state.todos || []; for (let i = 0; i < todos.length; i++) { if (todos[i].id === id) { todos[i].done = !todos[i].done; break; } } state.todos = todos; renderTodos(); } function deleteTodo(id) { let todos = state.todos || []; state.todos = todos.filter(t => t.id !== id); renderTodos(); } function updateCount() { const count = root.byId['count']; if (!count) return; let todos = state.todos || []; const remaining = todos.filter(t => !t.done).length; const total = todos.length; count.text = `${remaining} task${remaining !== 1 ? 's' : ''} remaining${total > 0 && remaining === 0 ? ' — all done! 🎉' : '.'}${total > 0 ? ` (${remaining}/${total})` : ''}`; } state.todos = [ { id: 'task-1', text: 'Book a cabin in the mountains', done: false }, { id: 'task-2', text: 'Pack hiking gear and snacks', done: true }, { id: 'task-3', text: 'Check weather forecast for Saturday', done: false } ]; root.byId['add-form'].on = { submit: () => addItem() }; root.byId['add-btn'].on = { click: () => addItem() }; renderTodos();"
  ]
}
